import{_ as p,a0 as o,w as a,s as u,ao as n,I as r,a1 as l,A as s,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"使用树莓派建立一个带有移动网络连接功能的路由器 | LCTT x X-CMD","titleTemplate":false,"description":"使用树莓派建立一个带有移动网络连接功能的路由器 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用树莓派建立一个带有移动网络连接功能的路由器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用树莓派建立一个带有移动网络连接功能的路由器 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20210312 Build a router with mobile connectivity using Raspberry Pi","title":"使用树莓派建立一个带有移动网络连接功能的路由器","tag":"202204","desc":""},"relativePath":"202204/20210312 Build a router with mobile connectivity using Raspberry Pi.md","filePath":"[post].md"}'),d={name:"202204/20210312 Build a router with mobile connectivity using Raspberry Pi.md"};function b(f,t,g,m,y,w){const i=o("Link");return a(),u("div",null,[t[49]||(t[49]=n('<h1 id="使用树莓派建立一个带有移动网络连接功能的路由器" tabindex="-1">使用树莓派建立一个带有移动网络连接功能的路由器 <a class="header-anchor" href="#使用树莓派建立一个带有移动网络连接功能的路由器" aria-label="Permalink to “使用树莓派建立一个带有移动网络连接功能的路由器”">​</a></h1><blockquote><p>在你的网络路由器上使用 OpenWRT 获得更多控制功能。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/mesh_networking_dots_connected.png?itok=ovINTRR3" alt="Mesh networking connected dots" title="Mesh networking connected dots"></p><p>树莓派是一种小型单板电脑，尽管只有信用卡大小，但是能做许多事情。实际上，这个小电脑几乎可以成为你想让它成为的任何东西，只要你打开想象力。</p><p>树莓派爱好者已经做了许多不同的项目，从简单的程序到复杂的自动化项目和解决方案，如气象站，甚至智能家居设备。这篇文章将展示怎样使用 OpenWRT 项目将你的树莓派变成带有 LTE 移动网络连接功能的路由器。</p><h3 id="关于-openwrt-和-lte" tabindex="-1">关于 OpenWRT 和 LTE <a class="header-anchor" href="#关于-openwrt-和-lte" aria-label="Permalink to “关于 OpenWRT 和 LTE”">​</a></h3>',6)),r("p",null,[l(i,{href:"https://openwrt.org/"},{default:s(()=>[...t[0]||(t[0]=[e("OpenWRT",-1)])]),_:1}),t[1]||(t[1]=e(" 是一个利用 Linux 内核为嵌入式设备开发的开源项目，它已经存在超过 15 年了，拥有一个庞大而活跃的社区。",-1))]),t[50]||(t[50]=r("p",null,"有许多使用 OpenWRT 的方法，但是它的主要目的还是用在路由器上。它提供了包管理功能和一个完全可写的文件系统，并且因为它的的开源属性，你可以查看和修改代码，并贡献到开源生态。如果你想对你的路由器获得更多的控制，这就是你想要的系统。",-1)),t[51]||(t[51]=r("p",null,[r("ruby",null,[e("长期演进技术"),r("rt",null,"Long-term evolution")]),e("（LTE）是一个基于 GSM/EGDE 和 UMTS/HSPA 技术的无线宽带通信标准。我使用的 LTE 调制解调器是一个 USB 设备，可以为树莓派电脑增加 3G 或 4G（LTE）蜂窝连接。")],-1)),t[52]||(t[52]=r("p",null,[r("img",{src:"https://opensource.com/sites/default/files/uploads/lte_modem.png",alt:"Teltonika TRM240 modem",title:"Teltonika TRM240 modem"})],-1)),t[53]||(t[53]=r("h3",{id:"安装前的准备",tabindex:"-1"},[e("安装前的准备 "),r("a",{class:"header-anchor",href:"#安装前的准备","aria-label":"Permalink to “安装前的准备”"},"​")],-1)),t[54]||(t[54]=r("p",null,"对这个项目来说，你需要：",-1)),r("ul",null,[t[5]||(t[5]=r("li",null,"一个带有电源线的树莓派",-1)),t[6]||(t[6]=r("li",null,"一台运行　Linux　的电脑",-1)),t[7]||(t[7]=r("li",null,"一张至少 16GB 的 SD 储存卡",-1)),t[8]||(t[8]=r("li",null,"以太网线",-1)),r("li",null,[t[3]||(t[3]=e("LTE 调制解调器（我使用的是 Teltonika ",-1)),l(i,{href:"https://teltonika-networks.com/product/trm240/"},{default:s(()=>[...t[2]||(t[2]=[e("TRM240",-1)])]),_:1}),t[4]||(t[4]=e("）",-1))]),t[9]||(t[9]=r("li",null,"一张移动网络的 SIM 卡",-1))]),t[55]||(t[55]=r("h3",{id:"安装-openwrt",tabindex:"-1"},[e("安装 OpenWRT "),r("a",{class:"header-anchor",href:"#安装-openwrt","aria-label":"Permalink to “安装 OpenWRT”"},"​")],-1)),r("p",null,[t[11]||(t[11]=e("首先，下载最新的 ",-1)),l(i,{href:"https://downloads.openwrt.org/releases/19.07.7/targets/brcm2708/bcm2710/"},{default:s(()=>[...t[10]||(t[10]=[e("兼容树莓派的 OpenWRT 的发布版本",-1)])]),_:1}),t[12]||(t[12]=e("。在 OpenWRT 官网，你可以看到 4 个镜像：两个 ",-1)),t[13]||(t[13]=r("strong",null,"ext4",-1)),t[14]||(t[14]=e(" 文件系统的和两个 ",-1)),t[15]||(t[15]=r("strong",null,"squashfs",-1)),t[16]||(t[16]=e(" 文件系统的。我使用 ",-1)),t[17]||(t[17]=r("strong",null,"ext4",-1)),t[18]||(t[18]=e(" 文件系统。你可以下载 ",-1)),t[19]||(t[19]=r("strong",null,"factory",-1)),t[20]||(t[20]=e(" 或者 ",-1)),t[21]||(t[21]=r("strong",null,"sysupgrade",-1)),t[22]||(t[22]=e(" 镜像，这两个都运行良好。",-1))]),t[56]||(t[56]=r("p",null,[r("img",{src:"https://opensource.com/sites/default/files/uploads/imagefiles.png",alt:"OpenWRT image files",title:"OpenWRT image files"})],-1)),r("p",null,[t[24]||(t[24]=e("下载了镜像后，你按照 ",-1)),l(i,{href:"https://opensource.com/article/17/3/how-write-sd-cards-raspberry-pi"},{default:s(()=>[...t[23]||(t[23]=[e("以下的说明",-1)])]),_:1}),t[25]||(t[25]=e(" 需要解压并安装它到 SD 卡上。这将会花些时间安装固件，需要些耐心。一旦安装完成，在你的 SD 卡上将会有两个分区。一个是用来放 bootloader ，另一个是 OpenWRT 系统。",-1))]),t[57]||(t[57]=n('<h3 id="启动系统" tabindex="-1">启动系统 <a class="header-anchor" href="#启动系统" aria-label="Permalink to “启动系统”">​</a></h3><p>要启动你的新系统，插入 SD 卡到树莓派，用以太网线把树莓派和你的路由器（或者交换机）相连，然后点亮。</p><p>如果你有使用树莓派的经验，你可能习惯于通过终端使用 SSH 访问过它，或者通过显示器和键盘连接到树莓派。OpenWRT 工作有一点点不同。你与这个系统交互是通过网页浏览器，所以你必须能够通过网络来访问你的树莓派。</p><p>缺省状态下，树莓派使用的 IP 地址是：192.168.1.1。用来配置树莓派的计算机必须和树莓派在同一个子网中。如果你的网络没有使用 192.168.1.x 地址，或者你不能确定，在 GNOME 打开 “<ruby>设置<rt>Settings</rt></ruby>” ，导航到网络设置，选择 “<ruby>手动<rt>Manual</rt></ruby>” ，然后键入以下的 IP 地址和子网掩码：</p><ul><li>IP 地址：192.168.1.15</li><li>网络掩码：255.255.255.0</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/ipaddresses.png" alt="IP addresses" title="IP addresses"></p><p>在你的电脑上打开浏览器然后导航到 192.168.1.1 。这将打开一个验证网页，你可以登录到你的树莓派。</p><p><img src="https://opensource.com/sites/default/files/uploads/openwrt-login.png" alt="OpenWRT login page" title="OpenWRT login page"></p><p>首次登录不需要密码，所以直接点击 “<ruby>登录<rt>Login</rt></ruby>” 按钮继续。</p><h3 id="设置网络连接" tabindex="-1">设置网络连接 <a class="header-anchor" href="#设置网络连接" aria-label="Permalink to “设置网络连接”">​</a></h3><p>树莓派只有一个以太网口，而普通路由器有两个：一个是 WAN（有线区域网络）口，另一个是 LAN （本地区域网络）。</p><p>你有两个选择：</p><ol><li>使用你的以太网口接入互联网</li><li>使用 WIFI 接入互联网</li></ol><h4 id="使用以太网连接" tabindex="-1">使用以太网连接 <a class="header-anchor" href="#使用以太网连接" aria-label="Permalink to “使用以太网连接”">​</a></h4><p>你决定使用以太网，导航到 “<ruby>网络<rt>Network</rt></ruby> → <ruby>接口<rt>Interfaces</rt></ruby>”。在这个设置页面，按下与 “LAN” 接口对应的蓝色 “<ruby>编辑<rt>Edit</rt></ruby>” 按钮。</p><p><img src="https://opensource.com/sites/default/files/uploads/lan-interface.png" alt="LAN interface" title="LAN interface"></p><p>应该会出现一个弹窗，在这个窗口中，你需要键入与你将要连接树莓派的路由器子网匹配的 IP 地址。如果需要的话，修改子网掩码，并输入树莓派将要连接的路由器的 IP 地址。</p><p><img src="https://opensource.com/sites/default/files/uploads/lan-interface-ip.png" alt="Enter IP in the LAN interface" title="Enter IP in the LAN interface"></p><p>保存设置，然后通过以太网将你的树莓派连接到路由器。你现在可以用这个新的 IP 地址访问树莓派。</p><p>当你在把树莓派投入生产环境使用之前，确保为你的 OpenWRT 设置一个密码！</p><h4 id="使用-wifi-连接" tabindex="-1">使用 WiFi 连接 <a class="header-anchor" href="#使用-wifi-连接" aria-label="Permalink to “使用 WiFi 连接”">​</a></h4><p>如果你想通过 WiFi 将树莓派连接到互联网，导航到 “<ruby>网络<rt>Network</rt></ruby> → <ruby>无线<rt>Wireless</rt></ruby>” 。在 “<ruby>无线<rt>Wireless</rt></ruby>” 菜单里，按下蓝色的 “<ruby>扫描<rt>Scan</rt></ruby>” 按钮查找你的家庭网络。</p><p><img src="https://opensource.com/sites/default/files/uploads/scannetwork.png" alt="Scan the network" title="Scan the network"></p><p>在弹出的窗口中，找到你的 WiFi 网络然后连接它。不要忘记 “<ruby>保存并应用<rt>Save and Apply</rt></ruby>” 设置。</p><p>在这 “<ruby>网络<rt>Network</rt></ruby> → <ruby>接口<rt>Interfaces</rt></ruby>” 部分，你应该看到了一个新的接口。</p><p><img src="https://opensource.com/sites/default/files/uploads/newinterface.png" alt="New interface" title="New interface"></p><p>当你在把树莓派投入生产环境使用之前，确保为你的 OpenWRT 设置一个密码！</p><h3 id="安装必要的软件包" tabindex="-1">安装必要的软件包 <a class="header-anchor" href="#安装必要的软件包" aria-label="Permalink to “安装必要的软件包”">​</a></h3><p>默认状态下，路由器并没有安装许多软件包。OpenWRT 提供了一个包管理器，带有一系列你需要安装的。导航到 “<ruby>系统<rt>System</rt></ruby> → <ruby>软件<rt>Software</rt></ruby>” 然后通过按下标有 “<ruby>更新列表…<rt>Update lists...</rt></ruby>” 的按钮来更新你的包管理器。</p><p><img src="https://opensource.com/sites/default/files/uploads/updatesoftwarelist.png" alt="Updating packages" title="Updating packages"></p><p>你将会看到许多软件包；你需要安装以下这些：</p><ul><li><code>usb-modeswitch</code></li><li><code>kmod-mii</code></li><li><code>kmod-usb-net</code></li><li><code>kmod-usb-wdm</code></li><li><code>kmod-usb-serial</code></li><li><code>kmod-usb-serial-option</code></li><li><code>kmod-usb-serial-wwan</code>（如果没有安装的话）</li></ul>',32)),r("p",null,[t[27]||(t[27]=e("另外，",-1)),l(i,{href:"https://downloads.openwrt.org/releases/packages-21.02/aarch64_cortex-a53/luci/luci-proto-modemmanager_git-21.007.43644-ab7e45c_all.ipk"},{default:s(()=>[...t[26]||(t[26]=[e("下载这个调制解调器管理软件包",-1)])]),_:1}),t[28]||(t[28]=e("，然后在弹出的窗口中按下标有 “",-1)),t[29]||(t[29]=r("ruby",null,[e("上传软件包…"),r("rt",null,"Upload Package...")],-1)),t[30]||(t[30]=e("” 的按钮来安装它。重启树莓派让安装包生效。",-1))]),t[58]||(t[58]=r("h3",{id:"设置移动网络接口",tabindex:"-1"},[e("设置移动网络接口 "),r("a",{class:"header-anchor",href:"#设置移动网络接口","aria-label":"Permalink to “设置移动网络接口”"},"​")],-1)),r("p",null,[t[32]||(t[32]=e("所有这些软件包被安装完之后，你可以设置移动网络接口。在连接调制解调器到树莓派之前，请阅读 ",-1)),l(i,{href:"https://wiki.teltonika-networks.com/view/TRM240_SIM_Card"},{default:s(()=>[...t[31]||(t[31]=[e("调制解调器的说明书",-1)])]),_:1}),t[33]||(t[33]=e("，对其进行设置。然后连接你的移动调制解调器到树莓派，然后等待一会直到调制解调器启动。",-1))]),t[59]||(t[59]=n('<p>导航到 “<ruby>网络<rt>Network</rt></ruby> → <ruby>接口<rt>Interfaces</rt></ruby>”。在页面底部，按下 “<ruby>添加一个新接口…<rt>Add new interface...</rt></ruby>” 按钮。在弹出的窗口中，给你的接口起一个名字（比如 “mobile”），然后从下拉列表中选择 “ModemManager” 。</p><p><img src="https://opensource.com/sites/default/files/uploads/addnewinterface.png" alt="Add a new mobile interface" title="Add a new mobile interface"></p><p>按下一个标有 “<ruby>创建接口<rt>Create Interface</rt></ruby>” 的按钮。你应该看到一个新的弹出窗口。这是设置接口的一个主窗口。在这个窗口中，选择你的调制解调器，然后键入像<ruby>接入点名称<rt>Access Point Name</rt></ruby>（APN）或是 PIN 码之类的信息。</p><p><img src="https://opensource.com/sites/default/files/uploads/configureinterface.png" alt="Configuring the interface" title="Configuring the interface"></p><p><strong>注意：</strong> 如果在列表中没有调制解调器设备出现，尝试重启树莓派或者安装 <code>kmod-usb-net-qmi-wwan</code> 软件包 。</p><p>当你已经配置完你的接口，按下 “<ruby>保存<rt>Save</rt></ruby>” 然后 “<ruby>保存并应用<rt>Save and Apply</rt></ruby>”。给系统一些生效的时间。如果一切正常，你应该看到像这样的一些东西。</p><p><img src="https://opensource.com/sites/default/files/uploads/configuredinterface.png" alt="Configured interface" title="Configured interface"></p><p>如果你想通过接口查看你的网络连接，你可以使用 SSH 连接到你的树莓派 shell。在终端里，键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh root@192.168.1.1</span></span></code></pre></div><p>缺省 IP 地址是 192.168.1.1：如果你修改了它，就用修改后的 IP 地址连接。当连接后，在终端里执行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ping -I ppp0 google.com</span></span></code></pre></div><p>如果一切正常运行，那么你应该从 Google 的服务器接收到 ping 回包 。</p><p><img src="https://opensource.com/sites/default/files/uploads/terminal.png" alt="Terminal interface" title="Terminal interface"></p><p><code>ppp0</code> 是你创建的移动网络接口的默认接口名称。你可以通过使用 <code>ifconfig</code> 命令检查你的接口。它只显示活动的接口。</p><h3 id="设置防火墙" tabindex="-1">设置防火墙 <a class="header-anchor" href="#设置防火墙" aria-label="Permalink to “设置防火墙”">​</a></h3><p>要让移动网接口运行，你需要为移动网络接口和本地网络接口配置防火墙，以便引导流量到正确的接口。</p><p>导航到 “<ruby>网络<rt>Network</rt></ruby> → <ruby>防火墙<rt>Firewall</rt></ruby>”。在页面的底部，你应该看到一个叫做 “<ruby>区域<rt>Zones</rt></ruby>” 的部分。</p><p><img src="https://opensource.com/sites/default/files/uploads/firewallzones.png" alt="Firewall zones" title="Firewall zones"></p><p>设置防火墙最简单的方法就是调整 “wan” 区域。在 “<ruby>已覆盖的网络<rt>Covered networks</rt></ruby>” 选项里按下 “<ruby>编辑<rt>Edit</rt></ruby>” 按钮，选择你的移动网络接口，然后 “<ruby>保存并应用<rt>Save and Apply</rt></ruby>” 你的设置。如果你不想用 WiFi 连接你的树莓派，你可以从 “<ruby>已覆盖的网络<rt>Covered networks</rt></ruby>” 里删除 “wwan” 接口，或者关闭 WiFi 连接。</p><p><img src="https://opensource.com/sites/default/files/uploads/firewallzonesettings.png" alt="Firewall zone settings" title="Firewall zone settings"></p><p>如果你想为每个接口设置一个独立区域，只需创建一个新区域然后分配必要的接口即可。举个例子，你可能想有一个覆盖移动网络接口的区域，并且通过它来转发 LAN 接口流量。按下 “<ruby>添加<rt>Name</rt></ruby>” 按钮，然后给你的区域 “<ruby>命名<rt>Name</rt></ruby>”， 检查 “伪装” 复选框，选中 “<ruby>已覆盖的网络<rt>Covered networks</rt></ruby>” ，并选择哪些区域可以转发其流量。</p><p><img src="https://opensource.com/sites/default/files/uploads/firewallzonepriv.png" alt="Firewall zone settings" title="Firewall zone settings"></p><p>然后 “<ruby>保存并应用<rt>Save and Apply</rt></ruby>” 这些修改。现在你有一个新的区域。</p><h3 id="设置一个接入点" tabindex="-1">设置一个接入点 <a class="header-anchor" href="#设置一个接入点" aria-label="Permalink to “设置一个接入点”">​</a></h3><p>最后一步是为你的设备接入互联网设置一个网络接入点。要设置一个接入点，导航到 “<ruby>网络<rt>Network</rt></ruby> → <ruby>无线<rt>Wireless</rt></ruby>” 。你将会看到一个 WiFi 设备接口，一个名为 OpenWRT 的禁用的接入点，以及一个用于通过 WiFi 连接互联网的连接（如果你之前没有禁用或删除它）。在这个禁用的接口上，按下 “<ruby>编辑<rt>Edit</rt></ruby>” 按钮，然后 “<ruby>启用<rt>Enable</rt></ruby>” 该接口。</p><p><img src="https://opensource.com/sites/default/files/uploads/enablewirelessnetwork.png" alt="Enabling wireless network" title="Enabling wireless network"></p><p>如果你想，你可以通过编辑 “ESSID” 选项来修改接口名称。你也可以选择它要关联的网络。默认情况下，它会与 LAN 接口关联。</p><p><img src="https://opensource.com/sites/default/files/uploads/interfaceconfig.png" alt="Configuring the interface" title="Configuring the interface"></p><p>要为这个接口添加密码，选择 “<ruby>无线安全<rt>Wireless Security</rt></ruby>” 选项，选择 “WPA2-PSK” 加密方式然后在 “<ruby>密钥<rt>Key</rt></ruby>” 选项字段键入接口的密码。</p><p><img src="https://opensource.com/sites/default/files/uploads/interfacepassword.png" alt="Setting a password" title="Setting a password"></p><p>然后 “<ruby>保存并应用<rt>Save and Apply</rt></ruby>” 设置。如果设置正确的话，当用你的设备扫描可用接入点的话，你应该可以看到你分配了名称的新接入点。</p><h3 id="额外的软件包" tabindex="-1">额外的软件包 <a class="header-anchor" href="#额外的软件包" aria-label="Permalink to “额外的软件包”">​</a></h3><p>如果你愿意，你可以通过网页界面为你的路由器下载额外的软件包。只需到 “<ruby>系统<rt>System</rt></ruby> → <ruby>软件<rt>Software</rt></ruby>” 然后安装你想从列表或者互联网上下载的软件包并上传它。如果你在列表中没有看到任何软件包，请按下 “<ruby>更新列表…<rt>Update lists...</rt></ruby>” 按钮。</p><p>你也可以添加其他拥有适合与 OpenWRT 一起使用的软件包的仓库。软件包和它们的网页界面是分开安装的。软件包名称是以 “luci-” 开始的是网页界面软件包。</p><p><img src="https://opensource.com/sites/default/files/uploads/luci-packages.png" alt="Packages with luci- prefix" title="Packages with luci- prefix"></p><h3 id="试试看" tabindex="-1">试试看 <a class="header-anchor" href="#试试看" aria-label="Permalink to “试试看”">​</a></h3><p>这就是我的树莓派路由设置的过程。</p><p><img src="https://opensource.com/sites/default/files/uploads/raspberrypirouter.jpg" alt="Raspberry Pi router" title="Raspberry Pi router"></p><p>从树莓派建立一个路由器不是很困难。缺点是树莓派只有一个以太网接口。你可以用一个 USB-to-Ethernet 适配器来增加更多的网口。不要忘记在接口的网站上设置网口。</p><p>OpenWRT 支持大量的移动调制解调器，你可以用管理调制解调器的通用工具 modemmanager 为它们设置移动网络接口。</p><p>你有没有把你的树莓派当作路由器使用？请在评论中告诉我们情况。</p><hr>',42)),r("p",null,[t[35]||(t[35]=e("via: ",-1)),l(i,{href:"https://opensource.com/article/21/3/router-raspberry-pi"},{default:s(()=>[...t[34]||(t[34]=[e("https://opensource.com/article/21/3/router-raspberry-pi",-1)])]),_:1})]),r("p",null,[t[40]||(t[40]=e("作者：",-1)),l(i,{href:"https://opensource.com/users/lukasjan"},{default:s(()=>[...t[36]||(t[36]=[e("Lukas Janėnas",-1)])]),_:1}),t[41]||(t[41]=e(" 选题：",-1)),l(i,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[37]||(t[37]=[e("lujun9972",-1)])]),_:1}),t[42]||(t[42]=e(" 译者：",-1)),l(i,{href:"https://github.com/hwlilfe"},{default:s(()=>[...t[38]||(t[38]=[e("hwlife",-1)])]),_:1}),t[43]||(t[43]=e(" 校对：",-1)),l(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[39]||(t[39]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[46]||(t[46]=e("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[44]||(t[44]=[e("LCTT",-1)])]),_:1}),t[47]||(t[47]=e(" 原创编译，",-1)),l(i,{href:"https://linux.cn/"},{default:s(()=>[...t[45]||(t[45]=[e("Linux中国",-1)])]),_:1}),t[48]||(t[48]=e(" 荣誉推出",-1))])])}const P=p(d,[["render",b]]);export{h as __pageData,P as default};
